import test from 'node:test';import assert from 'node:assert/strict';import vm from 'node:vm';
import {renderApp} from '../src/ui.mjs';import {action,summary,CATALOG} from '../src/engine.mjs';
const now=Date.parse('2026-10-31T12:00Z'),market={prices:Object.fromEntries(CATALOG.map(c=>[c.id,{eur:100,local:110,currency:'USD',at:now-86400000,fetchedAt:now}])),rate:{annualPct:2.4,date:'2026-10-30',fetchedAt:now},events:[],updatedAt:now};
const run=(s,a)=>action(s,market,{requestId:crypto.randomUUID(),...a},now,{parent:true});
function fixture(){let s=run(null,{type:'open_account',name:'Ana <prueba>'});s=run(s,{type:'setup',config:{experience:'investing',salary:10,initial:0}});return run(s,{type:'receive'})}
async function harness(state=fixture(),failure=false){const handlers={},requests=[],root={innerHTML:'',addEventListener:(k,f)=>handlers[k]=f},misc={};const document={getElementById:id=>id==='app'?root:['status','modal','retry'].includes(id)?(misc[id]??={innerHTML:'',replaceChildren(){this.innerHTML=''}}):null,querySelectorAll:()=>[],querySelector:()=>null};let listener;const parent={postMessage(msg){requests.push(msg);if(msg.path==='/state')queueMicrotask(()=>listener({source:parent,data:{reply:true,channel:msg.channel,id:msg.id,...(failure?{error:'Sin conexión'}:{data:{state,summary:state?.config?summary(state,market,now):null,market,catalog:CATALOG,serverTime:now,parent:{configured:true}}})}}))}};const context={document,parent,console,crypto,structuredClone,Date,Intl,scrollTo(){},setTimeout:()=>1,clearTimeout(){},addEventListener:(k,f)=>{if(k==='message')listener=f}};context.window=context;vm.runInNewContext(renderApp().match(/<script>([\s\S]*)<\/script>/)[1],context);await new Promise(r=>setImmediate(r));return {root,requests,click:async attrs=>{const b={dataset:Object.fromEntries(Object.entries(attrs).filter(([k])=>k.startsWith('data-')).map(([k,v])=>[k.slice(5).replace(/-([a-z])/g,(_,c)=>c.toUpperCase()),v])),hasAttribute:k=>k in attrs};await handlers.click({target:{closest:()=>b}})}}}
test('home distinguishes virtual allowance from gains; no bill or goal navigation',async()=>{const h=await harness();assert.match(h.root.innerHTML,/Ana &lt;prueba&gt;/);assert.match(h.root.innerHTML,/Asignación mensual/);assert.match(h.root.innerHTML,/no es una ganancia/);assert.doesNotMatch(h.root.innerHTML,/data-section="house"|Mi meta|Gastos de casa/)});
test('all 20 companies and fund/bond/deposit categories are reachable without writes',async()=>{const h=await harness();await h.click({'data-go':'invest'});assert.equal((h.root.innerHTML.match(/data-asset=/g)||[]).length,20);await h.click({'data-asset':'GOOGL'});assert.match(h.root.innerHTML,/Waymo/);assert.match(h.root.innerHTML,/no es una inversión exclusiva/);await h.click({'data-back':''});for(const [group,text]of [['funds','Vanguard VT'],['bonds','iShares IEF'],['deposit','Plazo fijo educativo']]){await h.click({'data-group':group});assert.ok(h.root.innerHTML.includes(text))}assert.equal(h.requests.filter(x=>x.path==='/action').length,0)});
test('compound lab is clearly hypothetical and does not alter account',async()=>{const h=await harness();await h.click({'data-go':'lab'});assert.match(h.root.innerHTML,/números inventados/);assert.match(h.root.innerHTML,/no cambia tu cartera/);assert.match(h.root.innerHTML,/type="number"/);assert.equal(h.requests.length,1)});
test('learning and portfolio provide previous and main menu, including errors',async()=>{const h=await harness();await h.click({'data-go':'learn'});assert.match(h.root.innerHTML,/No pongas todo/);await h.click({'data-go':'portfolio'});assert.match(h.root.innerHTML,/Mi cartera/);await h.click({'data-back':''});assert.match(h.root.innerHTML,/La bolsa, paso a paso/);await h.click({'data-close':''});assert.equal(h.requests.at(-1).close,true);const bad=await harness(null,true);assert.match(bad.root.innerHTML,/Sin conexión/);await bad.click({'data-close':''});assert.equal(bad.requests.at(-1).close,true)});
